\title{Well-Founded Argumentation Frameworks Have a Unique Complete Extension}
\author{Aristotle}
\date{2026-07-13}

\begin{document}
\maketitle

\begin{abstract}
We study Dung's abstract argumentation frameworks---a set of arguments equipped
with a binary \emph{attack} relation---and the lattice-theoretic semantics built
on the \emph{defense operator}. Building on the fact that the grounded extension
(the least fixed point of the defense operator) is the least complete extension,
we settle the opposite extreme. We prove two structural results. First, in
\emph{every} framework, the grounded extension equals the intersection of all
complete extensions, and every stable extension is complete. Second, if the
attack relation is \emph{well-founded}, the framework has exactly one complete
extension: the grounded extension, which is then simultaneously stable,
preferred, admissible, and complete; the stable and preferred extensions are
likewise unique and equal to it. The proofs are elementary but delicate:
conflict-freeness of the grounded extension requires transfinite iteration of a
non-continuous monotone operator, and uniqueness under well-foundedness follows
from a well-founded induction establishing that the grounded extension attacks
everything it excludes.
\end{abstract}

\section{Introduction}

Abstract argumentation, introduced by Dung, provides a purely relational account
of defeasible reasoning: one discards the internal structure of arguments and
retains only \emph{who attacks whom}. A rich theory of rational acceptability
emerges, organized around several \emph{extension semantics}: sets of arguments
that can be collectively accepted under varying standards of caution and
commitment.

Among these, the \textbf{grounded extension} is the most skeptical. It is the
least fixed point of a monotone \emph{defense operator} and always exists by the
Knaster--Tarski theorem. Prior work established that the grounded extension is
conflict-free, complete, and the least complete extension. This paper answers the
complementary questions: how does the grounded extension relate to the family of
all complete extensions (it is their intersection), and when does a framework
admit a \emph{unique} complete extension (when the attack relation is
well-founded, in which case grounded, stable, and preferred semantics coincide).
The bridge is the notion of a \textbf{stable} extension, which we show is always
complete. The main theorem is due to Dung (1995, Theorem 30).

\section{Preliminaries}

Throughout, fix a set $A$ of \emph{arguments} and a binary \emph{attack relation}
$R$ on $A$; read $R(a,b)$ as ``$a$ attacks $b$.'' The pair $(A,R)$ is an
\textbf{argumentation framework}. We impose no finiteness assumption.

\begin{definition}[Conflict-free]
$S \subseteq A$ is \emph{conflict-free} if
$\forall a \in S,\ \forall b \in S,\ \lnot R(a,b)$.
\end{definition}

\begin{definition}[Defense]
$S$ \emph{defends} an argument $a$ if every attacker of $a$ is counter-attacked
from $S$:
\[
\Defends(S,a) :\equiv \forall b,\ R(b,a) \Rightarrow \exists c \in S,\ R(c,b).
\]
\end{definition}

\begin{definition}[Defense operator]
The \emph{characteristic (defense) operator} $F \colon \Pow(A) \to \Pow(A)$ is
$F(S) = \{\, a \in A : \Defends(S,a) \,\}$.
\end{definition}

\begin{definition}[Admissible]
$S$ is \emph{admissible} if it is conflict-free and $S \subseteq F(S)$
(equivalently, defends each of its members).
\end{definition}

\begin{definition}[Complete extension]
$S$ is \emph{complete} if it is admissible and $F(S) \subseteq S$.
\end{definition}

\begin{definition}[Stable extension]
$S$ is \emph{stable} if it is conflict-free and attacks every argument outside it:
$\forall a \notin S,\ \exists b \in S,\ R(b,a)$.
\end{definition}

\begin{definition}[Preferred extension]
$S$ is \emph{preferred} if it is a maximal admissible set: admissible, and every
admissible $T \supseteq S$ satisfies $T = S$.
\end{definition}

\begin{definition}[Well-founded]
$R$ is \emph{well-founded} if there is no infinite sequence $(a_n)$ with
$R(a_{n+1}, a_n)$ for all $n$; equivalently, to prove $P(a)$ for all $a$ it
suffices to prove $P(a)$ under the hypothesis that $P(b)$ holds for all $b$ with
$R(b,a)$.
\end{definition}

\section{The defense operator and the grounded extension}

\begin{lemma}[Monotonicity]
If $S \subseteq T$ then $F(S) \subseteq F(T)$.
\end{lemma}
\begin{proof}
If $S$ defends $a$, each attacker $b$ of $a$ has a counter-attacker $c \in S
\subseteq T$; hence $T$ defends $a$.
\end{proof}

Thus $F$ is a monotone self-map of the complete lattice $(\Pow(A), \subseteq)$
and, by Knaster--Tarski, has a least fixed point.

\begin{definition}[Grounded extension]
The \emph{grounded extension} is $G = \lfp(F)$: $F(G) = G$, and $G \subseteq S$
for every $S$ with $F(S) \subseteq S$.
\end{definition}

Since $F$ need not preserve arbitrary suprema, the least fixed point is in general
reached only by \emph{transfinite} iteration: writing $F^{(\alpha)}$ for the
ordinal-indexed approximants from $\varnothing$, we have $G = F^{(\alpha)}$ for
some ordinal $\alpha$.

\begin{lemma}[Conflict-freeness]\label{lem:cf}
\begin{enumerate}
\item If $S$ is conflict-free, so is $F(S)$.
\item A directed union of conflict-free sets is conflict-free.
\item Every approximant $F^{(\alpha)}$ is conflict-free.
\item Hence $G$ is conflict-free.
\end{enumerate}
\end{lemma}
\begin{proof}
(1) If $a,b \in F(S)$ with $R(a,b)$, then since $b \in F(S)$ there is $c \in S$
with $R(c,a)$, and since $a \in F(S)$ there is $d \in S$ with $R(d,c)$;
but $c,d \in S$ and $R(d,c)$ contradict conflict-freeness of $S$.
(2) Any two elements of a directed union lie in a common conflict-free member.
(3) Transfinite induction: base $\varnothing$ vacuous; successors use (1); limits
use (2) since the approximants form an increasing chain.
(4) $G = F^{(\alpha)}$.
\end{proof}

We stress that conflict-freeness does \emph{not} follow from $F(S)=S$ alone;
there exist non-least fixed points that are conflicting. It is a property of the
\emph{least} fixed point.

\begin{proposition}[Characterization of completeness]
$S$ is complete iff $S$ is conflict-free and $F(S) = S$.
\end{proposition}
\begin{proof}
Completeness gives $S \subseteq F(S) \subseteq S$, so $F(S)=S$. Conversely a
conflict-free fixed point is admissible ($S \subseteq F(S)$) and closed
($F(S) \subseteq S$).
\end{proof}

\begin{corollary}
$G$ is admissible and complete.
\end{corollary}

\begin{proposition}[Grounded is least complete]\label{prop:least}
If $S$ is complete then $G \subseteq S$.
\end{proposition}
\begin{proof}
$F(S)\subseteq S$ makes $S$ a pre-fixed point, so $G = \lfp(F) \subseteq S$.
\end{proof}

\section{The intersection characterization}

\begin{theorem}[Grounded $=$ intersection of complete extensions]
In every framework, $G = \bigcap \{ S : S \text{ complete} \}$.
\end{theorem}
\begin{proof}
Let $\mathcal{C}$ be the complete extensions. Since $G \in \mathcal{C}$,
$\bigcap \mathcal{C} \subseteq G$. By Proposition~\ref{prop:least},
$G \subseteq S$ for all $S \in \mathcal{C}$, so $G \subseteq \bigcap \mathcal{C}$.
\end{proof}

\section{Stable extensions are complete}

\begin{theorem}[Stability implies completeness]\label{thm:stab}
Every stable extension is complete.
\end{theorem}
\begin{proof}
Let $S$ be stable: conflict-free ($\ast$) and total ($\dagger$: each $a\notin S$
has an attacker in $S$). For $a \in S$ and attacker $b$: if $b \in S$ then
$R(b,a)$ contradicts ($\ast$); so $b \notin S$ and by ($\dagger$) some $c \in S$
attacks $b$; thus $S$ defends $a$ and $S \subseteq F(S)$. For closure, suppose
$a \in F(S)$, $a \notin S$; by ($\dagger$) some $b \in S$ attacks $a$; since
$a \in F(S)$ some $c \in S$ attacks $b$; but $b,c \in S$ with $R(c,b)$
contradicts ($\ast$). Hence $a \in S$.
\end{proof}

Stability is strictly stronger than completeness: the two-cycle $\{a,b\}$ with
$R(a,b), R(b,a)$ has grounded extension $\varnothing$, while $\{a\}$ and $\{b\}$
are stable. Well-foundedness excludes such cycles.

\section{Well-founded frameworks: uniqueness}

Assume $R$ is well-founded.

\begin{theorem}[Grounded is stable]\label{thm:gstable}
If $R$ is well-founded, $G$ is stable.
\end{theorem}
\begin{proof}
$G$ is conflict-free by Lemma~\ref{lem:cf}. We prove totality by well-founded
induction on $R$ of
\[
P(a):\quad a \in G \ \lor\ \exists b \in G,\ R(b,a).
\]
Assume $P(b)$ for all $b$ with $R(b,a)$. If some attacker of $a$ lies in $G$, the
right disjunct holds. Otherwise no attacker of $a$ is in $G$; each attacker $b$
satisfies $R(b,a)$, so $P(b)$ holds, and since $b \notin G$ there is $c \in G$
with $R(c,b)$. Thus $G$ defends $a$, so $a \in F(G) = G$: the left disjunct
holds. Totality follows.
\end{proof}

\begin{theorem}[Complete $\subseteq$ grounded]\label{thm:sub}
If $R$ is well-founded and $S$ is complete, then $S \subseteq G$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:gstable}, $G$ is stable, and $G \subseteq S$ by
Proposition~\ref{prop:least}. If $a \in S \setminus G$, stability gives
$b \in G$ with $R(b,a)$; then $b \in G \subseteq S$ and $a \in S$ contradict
conflict-freeness of $S$. Hence $S \subseteq G$.
\end{proof}

\begin{theorem}[Uniqueness]
If $R$ is well-founded, $G$ is the unique complete extension; every complete
extension equals $G$.
\end{theorem}
\begin{proof}
$G$ is complete, and any complete $S$ satisfies $G \subseteq S$
(Proposition~\ref{prop:least}) and $S \subseteq G$ (Theorem~\ref{thm:sub}).
\end{proof}

\begin{corollary}[Stable uniqueness]
If $R$ is well-founded, $G$ is the unique stable extension.
\end{corollary}
\begin{proof}
$G$ is stable (Theorem~\ref{thm:gstable}); any stable $S$ is complete
(Theorem~\ref{thm:stab}), hence equals $G$.
\end{proof}

\begin{theorem}[Coincidence of semantics]
If $R$ is well-founded, $G$ is the unique preferred extension and the largest
complete extension; grounded, stable, and preferred semantics coincide.
\end{theorem}
\begin{proof}
Every preferred extension is complete (a maximal admissible set is closed under
defense), hence equals $G$ by uniqueness; and $G$, being the only complete
extension, is trivially the largest.
\end{proof}

\section{Worked examples}

\begin{example}[Well-founded chain]
$A = \{a,b,c\}$, $R = \{(a,b),(b,c)\}$. Kleene iteration gives
$\varnothing \to \{a\} \to \{a,c\} \to \{a,c\}$, so $G = \{a,c\}$: conflict-free,
attacks $b$, hence the unique stable, complete, and preferred extension.
\end{example}

\begin{example}[Two-cycle]
$A = \{a,b\}$, $R = \{(a,b),(b,a)\}$ (not well-founded). Complete extensions:
$\varnothing, \{a\}, \{b\}$; stable: $\{a\}, \{b\}$; intersection
$= \varnothing = G$. Uniqueness fails.
\end{example}

\begin{example}[Three-cycle]
$A=\{a,b,c\}$, $R=\{(a,b),(b,c),(c,a)\}$ (not well-founded). $G = \varnothing$,
no stable extensions, only complete extension $\varnothing$.
\end{example}

\section{Discussion and future directions}

Completeness alone permits many verdicts, and stability need not exist; the single
hypothesis of well-foundedness collapses grounded, stable, and preferred semantics
to a unique extension. The intersection characterization describes the grounded
extension, in any framework, as the semantic infimum of all complete positions.
Future work: (i) $\omega$-continuity and Kleene reachability
$G = \bigcup_n F^n(\varnothing)$ for finitary frameworks; (ii) preferred
$\Rightarrow$ complete without well-foundedness; (iii) labelling correspondence
(in/out/undec) and transport of uniqueness; (iv) quantitative bounds relating the
ordinal rank of $R$ to the stabilization stage of the approximants.

\begin{thebibliography}{9}
\bibitem{Dung1995} P. M. Dung, \emph{On the acceptability of arguments and its
fundamental role in nonmonotonic reasoning, logic programming and n-person games},
Artificial Intelligence \textbf{77} (1995), 321--357.
\end{thebibliography}

\end{document}

