"""Randomized stress test of the uniqueness theorem for well-founded
frameworks: generate random directed ACYCLIC graphs, then verify that each has
exactly one complete extension equal to the grounded = stable = preferred set."""
from __future__ import annotations
import random
from itertools import chain, combinations
from typing import FrozenSet, List, Set, Tuple

Argument = int
Framework = Tuple[FrozenSet[Argument], FrozenSet[Tuple[int, int]]]


def defends(af: Framework, s: Set[int], a: int) -> bool:
    _, atk = af
    return all(any((c, b) in atk for c in s)
               for b in (x for (x, y) in atk if y == a))


def F(af: Framework, s: Set[int]) -> Set[int]:
    return {a for a in af[0] if defends(af, s, a)}


def grounded(af: Framework) -> FrozenSet[int]:
    s: Set[int] = set()
    while (nxt := F(af, s)) != s:
        s = nxt
    return frozenset(s)


def conflict_free(af: Framework, s: Set[int]) -> bool:
    return all((a, b) not in af[1] for a in s for b in s)


def complete(af: Framework, s: Set[int]) -> bool:
    return (conflict_free(af, s) and all(defends(af, s, a) for a in s)
            and F(af, s) <= s)


def subsets(xs) -> List[FrozenSet[int]]:
    xs = list(xs)
    return [frozenset(c) for c in chain.from_iterable(
        combinations(xs, r) for r in range(len(xs) + 1))]


def random_dag(n: int, p: float) -> Framework:
    """Random acyclic framework: only edges i -> j with i < j (topological)."""
    args = frozenset(range(n))
    atk = frozenset((i, j) for i in range(n) for j in range(i + 1, n)
                    if random.random() < p)
    return (args, atk)


def main(trials: int = 500, n: int = 6, p: float = 0.35) -> None:
    random.seed(0)
    for _ in range(trials):
        af = random_dag(n, p)
        g = grounded(af)
        comps = [s for s in subsets(af[0]) if complete(af, set(s))]
        assert comps == [g], (af, comps, g)
    print(f"{trials} random well-founded frameworks (n={n}): "
          f"unique complete extension = grounded, every time.  OK")


if __name__ == "__main__":
    main()

"""Verify the Intersection Theorem on random (possibly cyclic) frameworks:
the grounded extension equals the intersection of all complete extensions."""
from __future__ import annotations
import random
from itertools import chain, combinations
from typing import FrozenSet, List, Set, Tuple

Framework = Tuple[FrozenSet[int], FrozenSet[Tuple[int, int]]]


def defends(af: Framework, s: Set[int], a: int) -> bool:
    _, atk = af
    return all(any((c, b) in atk for c in s)
               for b in (x for (x, y) in atk if y == a))


def F(af: Framework, s: Set[int]) -> Set[int]:
    return {a for a in af[0] if defends(af, s, a)}


def grounded(af: Framework) -> FrozenSet[int]:
    s: Set[int] = set()
    while (nxt := F(af, s)) != s:
        s = nxt
    return frozenset(s)


def complete(af: Framework, s: Set[int]) -> bool:
    cf = all((a, b) not in af[1] for a in s for b in s)
    return cf and all(defends(af, s, a) for a in s) and F(af, s) <= s


def subsets(xs) -> List[FrozenSet[int]]:
    xs = list(xs)
    return [frozenset(c) for c in chain.from_iterable(
        combinations(xs, r) for r in range(len(xs) + 1))]


def random_framework(n: int, p: float) -> Framework:
    args = frozenset(range(n))
    atk = frozenset((i, j) for i in range(n) for j in range(n)
                    if i != j and random.random() < p)
    return (args, atk)


def main(trials: int = 500, n: int = 5, p: float = 0.3) -> None:
    random.seed(1)
    for _ in range(trials):
        af = random_framework(n, p)
        g = grounded(af)
        comps = [set(s) for s in subsets(af[0]) if complete(af, set(s))]
        inter = set(af[0])
        for c in comps:
            inter &= c
        assert frozenset(inter) == g, (af, inter, g)
    print(f"{trials} random frameworks (n={n}): "
          f"grounded = intersection of complete extensions, every time.  OK")


if __name__ == "__main__":
    main()

