from __future__ import annotations
from typing import FrozenSet, Set, Tuple, Iterable

Argument = str
Attack = Tuple[Argument, Argument]
Framework = Tuple[FrozenSet[Argument], FrozenSet[Attack]]


def defends(af: Framework, s: Set[Argument], a: Argument) -> bool:
    """s defends a iff every attacker b of a is counter-attacked from s."""
    _, atk = af
    attackers = [x for (x, y) in atk if y == a]
    return all(any((c, b) in atk for c in s) for b in attackers)


def defense_operator(af: Framework, s: Set[Argument]) -> Set[Argument]:
    """F(S) = { a in A : S defends a }."""
    args, _ = af
    return {a for a in args if defends(af, s, a)}


def grounded_extension(af: Framework) -> FrozenSet[Argument]:
    """Least fixed point of the monotone defense operator F via Kleene
    iteration from the empty set. Terminates on finite frameworks."""
    s: Set[Argument] = set()
    while True:
        nxt = defense_operator(af, s)
        if nxt == s:
            return frozenset(s)
        s = nxt

