from itertools import chain, combinations
from typing import FrozenSet, Iterable, List, Set, Tuple

Argument = str
Framework = Tuple[FrozenSet[Argument], FrozenSet[Tuple[Argument, Argument]]]


def conflict_free(af: Framework, s: Set[Argument]) -> bool:
    _, atk = af
    return all((a, b) not in atk for a in s for b in s)


def defends(af: Framework, s: Set[Argument], a: Argument) -> bool:
    _, atk = af
    return all(any((c, b) in atk for c in s)
               for b in (x for (x, y) in atk if y == a))


def admissible(af: Framework, s: Set[Argument]) -> bool:
    return conflict_free(af, s) and all(defends(af, s, a) for a in s)


def complete(af: Framework, s: Set[Argument]) -> bool:
    args, _ = af
    return admissible(af, s) and {a for a in args if defends(af, s, a)} <= s


def stable(af: Framework, s: Set[Argument]) -> bool:
    args, atk = af
    return conflict_free(af, s) and all(
        any((b, a) in atk for b in s) for a in args - s)


def _subsets(args: Iterable[Argument]) -> Iterable[FrozenSet[Argument]]:
    args = list(args)
    return (frozenset(c) for c in chain.from_iterable(
        combinations(args, r) for r in range(len(args) + 1)))


def classify(af: Framework) -> dict:
    """Enumerate all subsets and classify them under each semantics.
    Preferred = maximal admissible sets under inclusion. Ground truth."""
    args = af[0]
    adm = [set(s) for s in _subsets(args) if admissible(af, set(s))]
    preferred = [frozenset(s) for s in adm if not any(s < t for t in adm)]
    return {
        "complete": [s for s in _subsets(args) if complete(af, set(s))],
        "stable": [s for s in _subsets(args) if stable(af, set(s))],
        "preferred": preferred,
    }

