"""Plot the Kleene iteration converging to the grounded extension: the size of
the approximant S_n = F^n(empty) as a function of the iteration index, for
several frameworks. Standalone: matplotlib only."""
from __future__ import annotations
from typing import FrozenSet, List, Set, Tuple

import matplotlib.pyplot as plt

Framework = Tuple[FrozenSet[str], FrozenSet[Tuple[str, str]]]


def defends(af: Framework, s: Set[str], a: str) -> bool:
    _, atk = af
    return all(any((c, b) in atk for c in s)
               for b in (x for (x, y) in atk if y == a))


def kleene_sizes(af: Framework) -> List[int]:
    s: Set[str] = set()
    sizes = [0]
    while True:
        nxt = {a for a in af[0] if defends(af, s, a)}
        sizes.append(len(nxt))
        if nxt == s:
            return sizes
        s = nxt


def chain_af(n: int) -> Framework:
    args = frozenset(f"x{i}" for i in range(n))
    atk = frozenset((f"x{i}", f"x{i+1}") for i in range(n - 1))
    return (args, atk)


if __name__ == "__main__":
    fig, ax = plt.subplots(figsize=(7, 4.5))
    for n in (3, 5, 7, 9):
        sizes = kleene_sizes(chain_af(n))
        ax.plot(range(len(sizes)), sizes, marker="o", label=f"chain n={n}")
    ax.set_xlabel("iteration k of S_k = F^k(empty)")
    ax.set_ylabel("|S_k|  (accepted arguments)")
    ax.set_title("Kleene iteration converging to the grounded extension")
    ax.legend(); ax.grid(True, alpha=0.3)
    plt.tight_layout(); plt.savefig("kleene_convergence.png", dpi=150)
    print("wrote kleene_convergence.png")
